        return;
    }

    onScroll();

    const timestamp = Date.now();

    if (scrollEndTimeout.current) {
        clearTimeout(scrollEndTimeout.current);
    }

    if (lastScrollEvent.current) {
        scrollEndTimeout.current = setTimeout(() => {
            if (lastScrollEvent.current !== timestamp) {
                return;
            }
            // Scroll has ended
            lastScrollEvent.current = null;
            onScrollEnd();
        }, 250);
    }

    lastScrollEvent.current = timestamp;
}, [enabled, inverted]);

return emitComposerScrollEvents;
```

This ensures referential stability and prevents unnecessary re-renders of components using this hook.

